import asyncio,json
from pathlib import Path
from playwright.async_api import async_playwright
OUT=Path('/tmp/browser/final')
async def login(page,id,path):
 await page.goto('http://localhost:8080/sign-in');await page.wait_for_timeout(3000);await page.locator('#auth-persona').select_option(id);await page.get_by_role('button',name='Continue',exact=True).click();await page.locator('.demo-tools button').first.filter(has_text='SAMPLE').wait_for();await page.goto('http://localhost:8080'+path);await page.locator('.demo-tools button').first.filter(has_text='SAMPLE').wait_for()
async def main():
 async with async_playwright() as p:
  b=await p.chromium.launch(headless=True);ctx=await b.new_context(viewport={'width':1280,'height':1800});page=await ctx.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));checks=[]
  await page.goto('http://localhost:8080/communications/verify');await page.wait_for_timeout(5000);await page.get_by_role('button',name='Request DEMO code',exact=True).click();await page.get_by_text('Code pending · DEMO',exact=False).wait_for();await page.locator('#comm-code').fill('123456');await page.get_by_role('button',name='Check DEMO code',exact=True).click();await page.get_by_text('Incorrect DEMO code',exact=False).wait_for();await page.locator('#comm-code').fill('000000');await page.get_by_role('button',name='Check DEMO code',exact=True).click();await page.get_by_role('link',name='Continue as this SAMPLE persona',exact=True).click();await page.locator('.demo-tools button').first.filter(has_text='SAMPLE').wait_for();checks.append('OTP wrong/correct and persona continuation PASS')
  await page.goto('http://localhost:8080/customer/addresses');await page.wait_for_timeout(2000);await page.get_by_role('button',name='Use my current location',exact=True).click();await page.get_by_role('alert').wait_for();assert not await page.locator('input[type=number]').first.input_value();checks.append('GPS denied/unavailable visible and no pin saved PASS');await page.screenshot(path=str(OUT/'gps.png'))
  await login(page,'sample-ops','/admin/dispatch');await page.wait_for_timeout(700);assert await page.get_by_text('This demo role cannot open this screen. Switch persona.',exact=True).count()==0;checks.append('Operations allowed dispatch PASS')
  await login(page,'sample-m1','/merchant/jobs/SAMPLE-999999');await page.wait_for_timeout(700);assert await page.get_by_text('Demo booking not found.',exact=True).count()>0;checks.append('Unknown merchant detail does not select unrelated job PASS')
  await login(page,'sample-admin','/admin/cities');await page.wait_for_timeout(700);await page.get_by_role('button',name='Add new',exact=True).click();dialog=page.get_by_role('dialog');await dialog.wait_for();await page.keyboard.press('Tab');assert await page.evaluate('!!document.activeElement.closest("[role=dialog]")');await page.keyboard.press('Escape');await dialog.wait_for(state='hidden');checks.append('CRUD dialog keyboard focus and Escape PASS')
  await page.goto('http://localhost:8080/communications/verify');await page.wait_for_timeout(1500);await page.get_by_role('button',name='తెలుగు',exact=True).first.click();await page.set_viewport_size({'width':320,'height':900});await page.screenshot(path=str(OUT/'otp320te.png'));assert await page.evaluate('document.documentElement.scrollWidth<=innerWidth');checks.append('Telugu OTP at 320 PASS')
  print(checks);print('errors',errors);(OUT/'focused.json').write_text(json.dumps({'checks':checks,'errors':errors},indent=2));await b.close()
asyncio.run(main())
